arguments.script:
var scene=UnityEngine.SceneManagement.SceneManager.CreateScene("Isolated motor checks",new UnityEngine.SceneManagement.CreateSceneParameters(UnityEngine.SceneManagement.LocalPhysicsMode.Physics2D));var physics=scene.GetPhysicsScene2D();
var host=new UnityEngine.GameObject("Isolated motor rig");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(host,scene);host.SetActive(false);
var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Prefabs/Character.prefab");var clone=UnityEngine.Object.Instantiate(prefab,host.transform);
foreach(var m in clone.GetComponentsInChildren<UnityEngine.MonoBehaviour>(true))if(!(m is Character.Control.TargetMovement)&&!(m is Character.Control.ArmsSimulation))UnityEngine.Object.DestroyImmediate(m);
host.SetActive(true);var arms=clone.GetComponentInChildren<Character.Control.ArmsSimulation>();var input=clone.GetComponentInChildren<Character.Control.TargetMovement>();input.enabled=false;input.ResetTarget();
var body=clone.transform.Find("Cauldron").GetComponent<UnityEngine.Rigidbody2D>();body.constraints=UnityEngine.RigidbodyConstraints2D.FreezeAll;
foreach(var rb in clone.GetComponentsInChildren<UnityEngine.Rigidbody2D>())rb.gravityScale=0;
void Tick(int n){for(int i=0;i<n;i++){arms.SendMessage("FixedUpdate");physics.Simulate(.02f);}}
try{
var field=typeof(Character.Control.TargetMovement).GetField("bodyCenter",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var origin=(UnityEngine.Vector2)((UnityEngine.Transform)field.GetValue(input)).position;
arms.ReceiveTarget(origin+UnityEngine.Vector2.right*1.9f);Tick(200);input.ResetTarget();
var previous=input.VirtualTarget;var slider=clone.GetComponentInChildren<UnityEngine.SliderJoint2D>();float previousAngle=slider.transform.eulerAngles.z,total=0;int stalls=0;float worst=0,maxStep=0;
for(int k=0;k<400;k++){
 float a=k*UnityEngine.Mathf.PI/100;var requested=origin+new UnityEngine.Vector2(UnityEngine.Mathf.Cos(a),UnityEngine.Mathf.Sin(a))*1.9f;
 input.ApplyRelativeMotion((requested-previous)/.006f);previous=requested;Tick(1);
 float angle=slider.transform.eulerAngles.z,step=UnityEngine.Mathf.DeltaAngle(previousAngle,angle);previousAngle=angle;
 if(k>100){total+=step;if(UnityEngine.Mathf.Abs(step)<.1f)stalls++;maxStep=UnityEngine.Mathf.Max(maxStep,UnityEngine.Mathf.Abs(step));}
 var axis=(UnityEngine.Vector2)slider.transform.right;var tip=(UnityEngine.Vector2)arms.HammerTip.position;
 for(int i=0;i<2;i++){UnityEngine.Vector2 shoulder=body.transform.position+body.transform.up*.66f+body.transform.right*(i==0?-.19f:.19f);worst=UnityEngine.Mathf.Max(worst,UnityEngine.Vector2.Distance(shoulder,tip-axis*((i==0?228:200)*2.15f/230)));}
}
UnityEngine.Debug.Log("Circle input: signed rotation(last299 ticks)="+total+" stalls="+stalls+" largest angular step="+maxStep+" max reach="+worst);
}finally{UnityEngine.Object.DestroyImmediate(host);UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(scene);}
